import { chromium } from '@playwright/test';
const cms='http://127.0.0.1:1337';
const web='http://127.0.0.1:8080';
const init=await fetch(cms+'/admin/init');
const result=await init.json();
console.log('Admin init status:', init.status, 'hasAdmin:', result.data?.hasAdmin);
const browser=await chromium.launch({channel:'chrome'});
try {
 const page=await browser.newPage();
 await page.route('**/*',route=>{
  const url=new URL(route.request().url());
  return [cms,web].includes(url.origin)?route.continue():route.abort();
 });
 const response=await page.goto(cms+'/admin');
 await page.locator('input[type=password]').first().waitFor({ timeout:10000 });
 console.log('Admin page status:', response?.status());
 console.log('Registration route:', new URL(page.url()).pathname);
 console.log('Field types:', await page.locator('input:not([type=hidden])').evaluateAll(nodes=>nodes.map(node=>node.type)));
 console.log('Registration button:', await page.locator('button[type=submit]').first().textContent());
 const frontendAdmin=await fetch(web+'/admin',{redirect:'manual'});
 const frontendAdminInit=await fetch(web+'/admin/init',{redirect:'manual'});
 console.log('Public app admin and admin/init status:',frontendAdmin.status,frontendAdminInit.status);
 for(const country of ['co','cl']){
  const content=await fetch(web+`/api/quote-content/v1/${country}/form`);
  const data=await content.json();
  console.log('Public seed:',country,content.status,data.country,data.fields?.length);
 }
} finally {
 await browser.close();
}
